/* ctipilot.ch — in-page filter UI for brief pages.
 *
 * The filter controls live inside the aside-toc on the right (and inside
 * the mobile collapsible "On this page"). All filter chips start in the
 * ACTIVE state (aria-pressed="true") — default view shows the entire
 * report. Clicking a chip flips it to inactive (aria-pressed="false"),
 * which negates that tag/region: items carrying that tag/region are then
 * hidden. Section toggles work the same way — click the eye icon next to
 * a section's TOC entry to hide that section.
 *
 * Multi-combo semantics:
 *   - Section visible iff its toggle is active.
 *   - Article visible iff:
 *       (1) its parent section is visible, AND
 *       (2) NONE of its data-tags is in the inactive-tag set, AND
 *       (3) NONE of its data-regions is in the inactive-region set.
 *
 * Untagged legacy items have no data-tags / data-regions and so are
 * never hidden by tag / region filters; they're only affected by the
 * section toggle.
 *
 * "Reset filters" button re-activates every chip.
 *
 * CSP-safe: external script, no inline handlers, no eval. Idempotent
 * binds; safe to load multiple times. No localStorage; state is
 * per-page-load.
 */
(function () {
  "use strict";
  function ready(fn) {
    if (document.readyState !== "loading") fn();
    else document.addEventListener("DOMContentLoaded", fn);
  }
  function tokens(str) {
    if (!str) return [];
    return ("" + str).split(/\s+/).filter(Boolean);
  }
  function bindBrief(root) {
    // The aside-toc is duplicated on the page (desktop + mobile). Bind
    // both copies; they share the same target articles in the body.
    var statusEl = root.querySelector('[data-role="filter-status"]');
    var resetBtn = root.querySelector('[data-action="clear-filters"]');
    var sectionToggles = root.querySelectorAll('[data-section-toggle]');
    var tagChips = root.querySelectorAll('[data-filter-tag]');
    var regionChips = root.querySelectorAll('[data-filter-region]');

    var articles = document.querySelectorAll(".brief-item");
    var sections = document.querySelectorAll(".brief-section");

    function inactiveSet(chips, attrCamel) {
      var out = {};
      chips.forEach(function (c) {
        if (c.getAttribute("aria-pressed") === "false") {
          out[c.dataset[attrCamel]] = true;
        }
      });
      return out;
    }
    function hiddenSectionSet() {
      var out = {};
      sectionToggles.forEach(function (b) {
        if (b.getAttribute("aria-pressed") === "false") {
          out[b.dataset.sectionToggle] = true;
        }
      });
      return out;
    }

    function applyFilters() {
      var inactiveTags = inactiveSet(tagChips, "filterTag");
      var inactiveRegs = inactiveSet(regionChips, "filterRegion");
      var hiddenSections = hiddenSectionSet();

      var anyChipFilter =
        Object.keys(inactiveTags).length > 0 ||
        Object.keys(inactiveRegs).length > 0;
      var anyFilter = anyChipFilter || Object.keys(hiddenSections).length > 0;

      var hiddenCount = 0;

      // Sections — driven by their TOC eye toggle. The eye toggle
      // COLLAPSES the section (heading remains, body folds) rather than
      // fully hiding it (the previous behaviour). The chevron on each
      // H2 in the body and the TOC eye toggle stay synced via the
      // `section-collapsed` class + the chevron's aria-expanded state.
      sections.forEach(function (sec) {
        var anchor = sec.id;
        var collapse = !!hiddenSections[anchor];
        sec.classList.toggle("section-collapsed", collapse);
        var chevron = sec.querySelector(".section-collapse-toggle");
        if (chevron) {
          chevron.setAttribute("aria-expanded", collapse ? "false" : "true");
        }
      });
      // Mark TOC rows as collapsed too so they look struck-through.
      document.querySelectorAll("[data-section-row]").forEach(function (row) {
        var anchor = row.dataset.sectionRow;
        row.classList.toggle("toc-row-hidden", !!hiddenSections[anchor]);
      });

      // Articles — hidden when any of their tags or regions is in the
      // inactive set (negation semantics).
      articles.forEach(function (art) {
        var tags = tokens(art.dataset.tags || "");
        var regs = tokens(art.dataset.regions || "");
        var hideByTag = tags.some(function (t) { return inactiveTags[t]; });
        var hideByReg = regs.some(function (r) { return inactiveRegs[r]; });
        var hidden = hideByTag || hideByReg;
        art.classList.toggle("filter-hidden", hidden);
        if (hidden) hiddenCount += 1;
      });

      // A section becomes "filter-section-empty" when chip filters hide
      // every one of its articles AND chip filters are active. Only
      // applies when the section isn't already explicitly collapsed.
      sections.forEach(function (sec) {
        if (sec.classList.contains("section-collapsed")) {
          sec.classList.remove("filter-section-empty");
          return;
        }
        var arts = sec.querySelectorAll(".brief-item");
        if (!arts.length) {
          sec.classList.remove("filter-section-empty");
          return;
        }
        var allHidden = true;
        arts.forEach(function (a) {
          if (!a.classList.contains("filter-hidden")) allHidden = false;
        });
        sec.classList.toggle("filter-section-empty", allHidden && anyChipFilter);
      });

      // Status line + reset visibility.
      if (statusEl) {
        if (anyFilter && hiddenCount > 0) {
          statusEl.textContent =
            hiddenCount + " item" + (hiddenCount === 1 ? "" : "s") + " hidden";
          statusEl.hidden = false;
        } else if (anyFilter) {
          statusEl.textContent = "Filters active";
          statusEl.hidden = false;
        } else {
          statusEl.hidden = true;
        }
      }
      if (resetBtn) resetBtn.hidden = !anyFilter;
      document.body.classList.toggle("filter-active", anyFilter);
    }

    function bindToggle(btn) {
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        var pressed = btn.getAttribute("aria-pressed") === "true";
        btn.setAttribute("aria-pressed", pressed ? "false" : "true");
        applyFilters();
      });
    }

    sectionToggles.forEach(bindToggle);
    tagChips.forEach(bindToggle);
    regionChips.forEach(bindToggle);

    if (resetBtn) {
      resetBtn.addEventListener("click", function () {
        sectionToggles.forEach(function (b) { b.setAttribute("aria-pressed", "true"); });
        tagChips.forEach(function (b) { b.setAttribute("aria-pressed", "true"); });
        regionChips.forEach(function (b) { b.setAttribute("aria-pressed", "true"); });
        applyFilters();
      });
    }
    applyFilters();
  }
  ready(function () {
    document.querySelectorAll('[data-filter="brief"]').forEach(bindBrief);
  });
})();
